insert into public.questions
(exam_category, subject, topic, type, difficulty, body, question_data, options, marks_correct, marks_wrong, explanation, concept_group_id, source_type, source_citation, status)
values
('upsc','Environment & Ecology','Ecosystems & Ecological Processes','statement_based','medium','Consider the following statements about ecological pyramids:','{"statements": ["The pyramid of energy is always upright.", "In the sea, the pyramid of biomass is generally inverted, because the biomass of fishes far exceeds that of the phytoplankton at any one time.", "The pyramid of numbers for a single large tree and the insects feeding on it is upright."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 1 and 2 are correct. Energy is lost as heat at every transfer, so the pyramid of energy can never be inverted. In the sea the standing crop of phytoplankton at any moment is smaller than the biomass of the fishes it supports (the phytoplankton turn over very fast), so the biomass pyramid is inverted. Statement 3 is wrong: one tree supports a great many insects, so that pyramid of numbers is inverted.','env-ecological-pyramids','original_pattern_matched','NCERT Biology Class XII, ch. ''Ecosystem'' (ecological pyramids).','draft'),
('upsc','Environment & Ecology','Ecosystems & Ecological Processes','statement_based','medium','Consider the following statements about ecological succession:','{"statements": ["In hydrarch succession, the series progresses from mesic towards hydric conditions.", "Primary succession begins where no soil existed before, such as on bare rock or newly cooled lava.", "Secondary succession is usually faster than primary succession, because soil is already present.", "The community that is in near-equilibrium with the environment at the end of a succession is called the climax community."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": true}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 2, 3 and 4 are correct. Primary succession starts where there was no soil; secondary succession, on abandoned farmland or burnt or felled forest, is faster because soil (and often seeds) remains. Succession ends in a climax community. Statement 1 reverses the direction: hydrarch succession runs from hydric (wet) towards mesic conditions, and xerarch succession from xeric towards mesic -- both converge on medium-moisture conditions.','env-succession-hydrarch','original_pattern_matched','NCERT Biology Class XII, ch. ''Ecosystem'' (ecological succession).','draft'),
('upsc','Environment & Ecology','Ecosystems & Ecological Processes','statement_based','medium','With reference to energy flow in ecosystems, consider the following statements:','{"statements": ["Roughly 10 per cent of the energy at one trophic level is passed on to the next.", "In aquatic ecosystems, the detritus food chain is the main conduit of energy flow.", "In terrestrial ecosystems, a much larger fraction of energy flows through the detritus food chain than through the grazing food chain."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true, "numbering": "roman"}'::jsonb,'[{"id": "a", "body": "I and II only", "isCorrect": false}, {"id": "b", "body": "II only", "isCorrect": false}, {"id": "c", "body": "II and III only", "isCorrect": false}, {"id": "d", "body": "I and III only", "isCorrect": true}]'::jsonb,2,0.66,'Statements I and III are correct. By Lindeman''s ten per cent law only about a tenth of the energy at one trophic level reaches the next. Statement II is the reversal: in aquatic ecosystems the grazing food chain is the major conduit for energy flow, whereas on land a much larger fraction flows through the detritus food chain.','env-energy-flow-food-chains','original_pattern_matched','NCERT Biology Class XII, ch. ''Ecosystem'' (energy flow; grazing and detritus food chains).','draft'),
('upsc','Environment & Ecology','Ecosystems & Ecological Processes','statement_based','medium','Consider the following statements:','{"statements": ["An ecotone is a zone of transition between two ecosystems, such as the belt where a forest meets a grassland.", "The number of species, and the density of some species, is often higher in an ecotone than in the adjoining communities; this is called the edge effect.", "A keystone species is, by definition, the most abundant species in its community."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 and 2 only", "isCorrect": true}, {"id": "b", "body": "2 and 3 only", "isCorrect": false}, {"id": "c", "body": "1 and 3 only", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. An ecotone mixes species of both neighbouring communities plus some of its own, which is why it is often richer -- the edge effect. Statement 3 is wrong: a keystone species is one whose influence on the community is disproportionately large relative to its abundance. The textbook case is the sea otter, whose predation on sea urchins keeps kelp forests from being grazed away; keystone species are often not abundant at all.','env-ecotone-keystone','original_pattern_matched','E. P. Odum, Fundamentals of Ecology (ecotones and the edge effect); R. T. Paine (1969), American Naturalist 103 (keystone species).','draft'),
('upsc','Environment & Ecology','Ecosystems & Ecological Processes','statement_based','easy','Consider the following statements:','{"statements": ["The atmosphere is the main reservoir of phosphorus.", "Atmospheric nitrogen can be fixed by lightning as well as by certain bacteria."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "2 only", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct. Phosphorus has a sedimentary cycle: its natural reservoir is rock, from which weathering releases phosphates, and unlike carbon there is no respiratory release of phosphorus into the atmosphere. Nitrogen is fixed both by lightning and industrial processes and biologically, by bacteria such as Rhizobium and by cyanobacteria.','env-phosphorus-nitrogen-cycles','original_pattern_matched','NCERT Biology Class XII, ch. ''Ecosystem'' (phosphorus cycle); NCERT Biology Class XI (pre-2023 edition), ch. ''Mineral Nutrition'' (nitrogen fixation).','draft'),
('upsc','Environment & Ecology','Ecosystems & Ecological Processes','statement_based','hard','Consider the following statements about productivity in ecosystems:','{"statements": ["Net primary productivity is gross primary productivity minus the energy the producers use in respiration.", "Secondary productivity is the rate at which producers form new organic matter.", "Although the oceans cover about 70 per cent of the Earth''s surface, they account for only about one-third of the biosphere''s annual net primary productivity.", "Primary productivity depends only on the plant species of an area, not on nutrient availability or other environmental factors."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "Only three", "isCorrect": false}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 1 and 3 are correct. NPP = GPP minus respiration losses, and NPP is what is available to consumers. Of the biosphere''s roughly 170 billion tonnes (dry weight) of annual NPP, the oceans produce only about 55 billion tonnes. Statement 2 is wrong: secondary productivity is the rate at which consumers form new organic matter. Statement 4 is wrong: primary productivity depends on the plant species and also on the environment, nutrient availability and the plants'' photosynthetic capacity.','env-productivity-npp','original_pattern_matched','NCERT Biology Class XII, ch. ''Ecosystem'' (productivity).','draft'),
('upsc','Environment & Ecology','Ecosystems & Ecological Processes','mcq','medium','Gause''s ''competitive exclusion principle'' states that:','{}'::jsonb,'[{"id": "a", "body": "a predator always keeps its prey population below the carrying capacity of the habitat", "isCorrect": false}, {"id": "b", "body": "a species always occupies the whole of its fundamental niche", "isCorrect": false}, {"id": "c", "body": "only about 10 per cent of the energy at one trophic level passes on to the next", "isCorrect": false}, {"id": "d", "body": "two closely related species competing for the same limiting resources cannot coexist indefinitely, and the competitively inferior one is eventually eliminated", "isCorrect": true}]'::jsonb,2,0.66,'Gause''s principle holds that two closely related species competing for the same resources cannot coexist indefinitely; the inferior competitor is eventually eliminated. It applies when the resources are limiting. Competitors can still coexist through resource partitioning, as in MacArthur''s warblers, which feed in different parts of the same tree. The third option is Lindeman''s ten per cent law.','env-competitive-exclusion','original_pattern_matched','NCERT Biology Class XII, ch. ''Organisms and Populations'' (population interactions: competition).','draft'),
('upsc','Environment & Ecology','Ecosystems & Ecological Processes','assertion_reason','medium','Consider the following statements:','{"assertion": "Soils under tropical rainforests are generally poor in nutrients.", "reason": "In tropical rainforests most nutrients are held in the living vegetation and are recycled quickly, because warm, humid conditions speed up decomposition.", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct and Statement-II explains Statement-I. Warmth and moisture make decomposition fast, and the released nutrients are taken up almost at once by the dense vegetation, so little accumulates in the soil; heavy rain leaches away much of the rest. That is why cleared rainforest land loses its fertility within a few seasons.','env-rainforest-soil-nutrients','original_pattern_matched','NCERT Biology Class XII, ch. ''Ecosystem'' (decomposition and the factors affecting its rate).','draft'),
('upsc','Environment & Ecology','Ecosystems & Ecological Processes','match_the_following','hard','Consider the following pairs of ecological terms and their meanings:','{"list_1": ["1. Ecotone", "2. Ecological niche", "3. Sere", "4. Standing crop"], "list_2": ["Zone of transition between two communities", "The physical place where an organism lives", "The sequence of communities that replace one another during a succession", "The amount of nutrients present in the soil at a given time"], "closing": "How many of the pairs given above are correctly matched?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "isCorrect": true}, {"id": "c", "body": "Only three pairs", "isCorrect": false}, {"id": "d", "body": "All four pairs", "isCorrect": false}]'::jsonb,2,0.66,'Only two pairs are correct: 1 and 3. Pair 2 describes a habitat; a niche is an organism''s functional role together with the full range of conditions and resources it uses. Pair 4 describes the standing state; the standing crop is the mass of living material at a trophic level at a particular time.','env-ecology-terms-pairs','original_pattern_matched','NCERT Biology Class XII, ch. ''Ecosystem'' (standing crop, standing state, seres); NCERT Biology Class XII, ch. ''Organisms and Populations'' (niche).','draft'),
('upsc','Environment & Ecology','Ecosystems & Ecological Processes','match_the_following','hard','Consider the following pairs of types of ecological succession and where they begin:','{"list_1": ["1. Hydrosere", "2. Lithosere", "3. Psammosere", "4. Xerosere"], "list_2": ["A water body", "Bare rock", "Saline soil or saline water", "A dry habitat"], "closing": "How many of the pairs given above are correctly matched?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "isCorrect": true}, {"id": "d", "body": "All four pairs", "isCorrect": false}]'::jsonb,2,0.66,'Only three pairs are correct: 1, 2 and 4. A psammosere begins on sand, such as coastal dunes; succession on saline soil or in saline water is a halosere. A lithosere (on rock) is one kind of xerosere.','env-seres-pairs','original_pattern_matched','E. P. Odum, Fundamentals of Ecology (ecological succession); NCERT Biology Class XII, ch. ''Ecosystem'' (ecological succession).','draft'),
('upsc','Environment & Ecology','International Conventions & Organisations','statement_based','medium','Consider the following statements about the Convention on Biological Diversity (CBD) and its protocols:','{"statements": ["The Cartagena Protocol deals with the safe transfer, handling and use of living modified organisms.", "The Nagoya-Kuala Lumpur Supplementary Protocol deals with liability and redress for damage caused by living modified organisms.", "The United States is a Party to the CBD."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 1 and 2 are correct. The Cartagena Protocol on Biosafety (2000) covers living modified organisms, and its Nagoya-Kuala Lumpur Supplementary Protocol (2010, in force 2018) adds rules on liability and redress. Statement 3 is wrong: the United States signed the CBD in 1993 but has never ratified it, so it is not a Party.','env-cbd-protocols','original_pattern_matched','CBD Secretariat, list of Parties; Cartagena Protocol on Biosafety (2000); Nagoya-Kuala Lumpur Supplementary Protocol on Liability and Redress (2010).','draft'),
('upsc','Environment & Ecology','International Conventions & Organisations','statement_based','medium','Consider the following statements about the Kunming-Montreal Global Biodiversity Framework:','{"statements": ["It was adopted at the fifteenth Conference of the Parties (COP15) to the Convention on Biological Diversity in December 2022.", "One of its targets is to effectively conserve at least 30 per cent of the world''s land and inland waters, and of its coastal and marine areas, by 2030.", "It sets 23 action-oriented global targets for 2030.", "It is a legally binding treaty that imposes penalties on countries that miss its targets."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": true}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 1, 2 and 3 are correct. The framework was adopted at CBD COP15 (held in Montreal under China''s presidency) in December 2022, with four goals for 2050 and 23 targets for 2030, including ''30 by 30'' (Target 3). Statement 4 is wrong: it is a decision of the Parties, not a treaty; countries report progress through national biodiversity strategies and action plans, and there are no penalties.','env-kunming-montreal-gbf','original_pattern_matched','CBD Decision 15/4, Kunming-Montreal Global Biodiversity Framework (December 2022).','draft'),
('upsc','Environment & Ecology','International Conventions & Organisations','statement_based','medium','Consider the following statements about the Convention on the Conservation of Migratory Species of Wild Animals (CMS):','{"statements": ["Its Secretariat is provided by the IUCN.", "It is also known as the Bonn Convention.", "India hosted its thirteenth Conference of the Parties (COP13) at Gandhinagar in 2020."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true, "numbering": "roman"}'::jsonb,'[{"id": "a", "body": "I and II only", "isCorrect": false}, {"id": "b", "body": "II and III only", "isCorrect": true}, {"id": "c", "body": "I and III only", "isCorrect": false}, {"id": "d", "body": "I, II and III", "isCorrect": false}]'::jsonb,2,0.66,'Statements II and III are correct. The CMS was signed at Bonn in 1979, hence the ''Bonn Convention'', and India hosted CMS COP13 at Gandhinagar in February 2020. Statement I is wrong: the CMS is an environmental treaty under the United Nations Environment Programme, which provides its Secretariat; the IUCN is a separate membership union.','env-cms-bonn','original_pattern_matched','CMS Secretariat (UNEP), convention text and COP13, Gandhinagar, February 2020.','draft'),
('upsc','Environment & Ecology','International Conventions & Organisations','statement_based','easy','Consider the following statements about the United Nations Environment Programme (UNEP):','{"statements": ["It is headquartered in Nairobi.", "It was set up following the 1972 United Nations Conference on the Human Environment at Stockholm."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "2 only", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. UNEP was established by the UN General Assembly in December 1972, following the Stockholm Conference, and has its headquarters in Nairobi, Kenya.','env-unep-stockholm','original_pattern_matched','UNEP, ''About the UN Environment Programme''; UN General Assembly resolution 2997 (XXVII), 1972.','draft'),
('upsc','Environment & Ecology','International Conventions & Organisations','statement_based','hard','Consider the following statements about the ''High Seas Treaty'' (the BBNJ Agreement):','{"statements": ["It is an agreement under the United Nations Convention on the Law of the Sea (UNCLOS).", "It applies to marine areas beyond national jurisdiction: the high seas and the international seabed area.", "It entered into force in January 2026, after the required 60 ratifications were reached.", "India has signed it."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": false}, {"id": "d", "body": "All four", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. The Agreement on Marine Biological Diversity of Areas beyond National Jurisdiction was adopted in 2023 as the third implementing agreement under UNCLOS. It covers the high seas and ''the Area'' (the international seabed). The 60th ratification came in September 2025, and it entered into force 120 days later, on 17 January 2026. India signed it in 2024. The difficulty is that each statement sounds plausible either way.','env-bbnj-high-seas','original_pattern_matched','UN, Agreement under UNCLOS on the Conservation and Sustainable Use of Marine Biological Diversity of Areas beyond National Jurisdiction (2023); UN Treaty Collection, status of the Agreement (in force 17 January 2026).','draft'),
('upsc','Environment & Ecology','International Conventions & Organisations','mcq','medium','The ''Living Planet Report'', which tracks the average change in monitored populations of wild vertebrates, is published by:','{}'::jsonb,'[{"id": "a", "body": "IUCN", "isCorrect": false}, {"id": "b", "body": "UNEP", "isCorrect": false}, {"id": "c", "body": "Wetlands International", "isCorrect": false}, {"id": "d", "body": "WWF", "isCorrect": true}]'::jsonb,2,0.66,'The Living Planet Report is published by WWF, with the Zoological Society of London compiling the Living Planet Index. Its 2024 edition reported an average decline of 73 per cent in monitored wildlife populations between 1970 and 2020. The IUCN publishes the Red List of Threatened Species.','env-living-planet-report','original_pattern_matched','WWF, Living Planet Report 2024 (Living Planet Index compiled by the Zoological Society of London).','draft'),
('upsc','Environment & Ecology','International Conventions & Organisations','assertion_reason','medium','Consider the following statements:','{"assertion": "The Montreal Protocol is regarded as a climate treaty as well as an ozone treaty.", "reason": "Many of the ozone-depleting substances it phases out, such as CFCs, are also potent greenhouse gases.", "reason_2": "Its Kigali Amendment (2016) requires the phase-down of hydrofluorocarbons (HFCs), which do not deplete the ozone layer but are powerful greenhouse gases.", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement II and Statement III are correct and both of them explain Statement I", "isCorrect": true}, {"id": "b", "body": "Both Statement II and Statement III are correct but only one of them explains Statement I", "isCorrect": false}, {"id": "c", "body": "Only one of the Statements II and III is correct and that explains Statement I", "isCorrect": false}, {"id": "d", "body": "Neither Statement II nor Statement III is correct", "isCorrect": false}]'::jsonb,2,0.66,'Both Statement II and Statement III are correct and both explain Statement I. Phasing out CFCs and other ozone-depleting substances, most of which are strong greenhouse gases, has already avoided a large amount of warming. The Kigali Amendment extended the Protocol to HFCs, the CFC substitutes that are harmless to ozone but potent greenhouse gases; their phase-down is expected to avoid up to about 0.4 degrees Celsius of warming by 2100.','env-montreal-kigali-climate','original_pattern_matched','UNEP Ozone Secretariat, Montreal Protocol on Substances that Deplete the Ozone Layer and its Kigali Amendment (2016).','draft'),
('upsc','Environment & Ecology','Indian Environmental Laws & Bodies','statement_based','medium','Consider the following statements about the National Green Tribunal (NGT):','{"statements": ["It can hear cases arising under the Wildlife (Protection) Act, 1972.", "It was set up under the National Green Tribunal Act, 2010.", "Its principal bench sits in New Delhi."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "1 and 2", "isCorrect": false}, {"id": "c", "body": "2 and 3", "isCorrect": true}, {"id": "d", "body": "3 only", "isCorrect": false}]'::jsonb,2,0.66,'Statements 2 and 3 are correct. The NGT was set up in 2010 under its own Act, with its principal bench in New Delhi. Statement 1 is wrong: the NGT decides cases under the laws listed in Schedule I of the NGT Act -- among them the Water, Air, Environment (Protection), Forest (Conservation) and Biological Diversity Acts -- and the Wildlife (Protection) Act and the Indian Forest Act are not among them.','env-ngt-jurisdiction','original_pattern_matched','National Green Tribunal Act, 2010, section 14 and Schedule I; National Green Tribunal, ''About us''.','draft'),
('upsc','Environment & Ecology','Indian Environmental Laws & Bodies','statement_based','medium','Consider the following statements about the Biological Diversity Act, 2002:','{"statements": ["The National Biodiversity Authority set up under it is headquartered in Chennai.", "It was enacted to give effect to India''s obligations under the Ramsar Convention.", "Since its 2023 amendment, registered AYUSH practitioners need not give prior intimation to the State Biodiversity Board to use biological resources in practising indigenous medicine as a profession."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 and 2 only", "isCorrect": false}, {"id": "b", "body": "2 and 3 only", "isCorrect": false}, {"id": "c", "body": "1 and 3 only", "isCorrect": true}, {"id": "d", "body": "1, 2 and 3", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. The National Biodiversity Authority sits in Chennai, and the Biological Diversity (Amendment) Act, 2023 extended the old exemption for vaids and hakims to registered AYUSH practitioners who practise for sustenance and livelihood. Statement 2 is wrong: the Act gives effect to the Convention on Biological Diversity (CBD); the Ramsar Convention concerns wetlands.','env-biodiversity-act-2023','original_pattern_matched','Biological Diversity Act, 2002; Biological Diversity (Amendment) Act, 2023 (No. 10 of 2023), section 7; National Biodiversity Authority.','draft'),
('upsc','Environment & Ecology','Indian Environmental Laws & Bodies','statement_based','easy','Consider the following statements about the National Tiger Conservation Authority (NTCA):','{"statements": ["It is a statutory body constituted under the Wildlife (Protection) Act, 1972.", "It is chaired by the Prime Minister."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": true}, {"id": "b", "body": "2 only", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. The NTCA was constituted in 2006 under section 38L of the Wildlife (Protection) Act, inserted by that year''s amendment, taking over from Project Tiger. It is chaired by the Union Minister for Environment, Forest and Climate Change, not the Prime Minister.','env-ntca-statutory','original_pattern_matched','Wildlife (Protection) Act, 1972, Chapter IVB (sections 38K-38X), inserted by the Wildlife (Protection) Amendment Act, 2006; NTCA, ''About us''.','draft'),
('upsc','Environment & Ecology','Indian Environmental Laws & Bodies','statement_based','hard','Consider the following statements about the Forest (Conservation) Amendment Act, 2023:','{"statements": ["It renamed the Forest (Conservation) Act, 1980 as the Van (Sanrakshan Evam Samvardhan) Adhiniyam, 1980.", "It exempts forest land within 100 km of India''s international borders, the Line of Control or the Line of Actual Control from the Act''s approval requirement when the land is needed for strategic linear projects of national importance and concerning national security.", "It bars zoos and safaris from forest land outside protected areas."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 and 2 only", "isCorrect": true}, {"id": "b", "body": "2 and 3 only", "isCorrect": false}, {"id": "c", "body": "1 and 3 only", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The amendment, in force from 1 December 2023, renamed the Act and created the border-area exemption for strategic linear projects. Statement 3 is the reverse of what it did: it added zoos and safaris (under the Wildlife (Protection) Act) owned by the Government or any authority in forest areas outside protected areas, together with eco-tourism facilities and silvicultural operations, to the activities that do not count as a non-forest purpose. (Separately, a February 2024 interim order of the Supreme Court requires its approval for any new zoo or safari on forest land.)','env-forest-conservation-amendment-2023','original_pattern_matched','Forest (Conservation) Amendment Act, 2023 (No. 15 of 2023); PRS Legislative Research, The Forest (Conservation) Amendment Bill, 2023.','draft'),
('upsc','Environment & Ecology','Indian Environmental Laws & Bodies','mcq','medium','Eco-Sensitive Zones around national parks and wildlife sanctuaries are notified by the Central Government under which of the following laws?','{}'::jsonb,'[{"id": "a", "body": "Wildlife (Protection) Act, 1972", "isCorrect": false}, {"id": "b", "body": "Forest (Conservation) Act, 1980", "isCorrect": false}, {"id": "c", "body": "Biological Diversity Act, 2002", "isCorrect": false}, {"id": "d", "body": "Environment (Protection) Act, 1986", "isCorrect": true}]'::jsonb,2,0.66,'Eco-Sensitive Zones are notified by the Ministry of Environment, Forest and Climate Change under section 3 of the Environment (Protection) Act, 1986, read with rule 5 of the Environment (Protection) Rules, 1986, which let the Centre restrict industries and processes in an area. The Wildlife (Protection) Act governs the protected areas themselves, not the buffer around them.','env-eco-sensitive-zones','original_pattern_matched','Environment (Protection) Act, 1986, section 3; Environment (Protection) Rules, 1986, rule 5; MoEFCC, Guidelines for Declaration of Eco-Sensitive Zones around National Parks and Wildlife Sanctuaries (2011).','draft')
